/* Analytics counts buyers' orders only, and reads refunds quickly (round ana-1028, run after part 61): the all time line under Revenue and Orders (`analytics_all_time`, Home's sales totals too) leaves out an admin's Test sale (an order whose `source_detail` says surface `admin`, written by the admin console's sales trigger), as every Analytics read in the app now does (lib/analytics/test-sales.ts); the function is otherwise part 61's, word for word. And a partial index on `orders (creator_id, refunded_at) WHERE status = 'refunded'`, for the read every Analytics answer makes of refunds given in the period of orders placed before it (lib/analytics/report-read refundedEarlier), which scanned all of a store's orders, and one on `ledger_events (creator_id, created_at) WHERE event_type = 'refund'` for the refunds dated on the seller's ledger in the period (lib/analytics/refund-history-server refundedOrderIds), which scanned every ledger row of the store; each skipped where its table or columns are not there yet. No row changes. Until it runs, the all time line still counts test sales as orders (they never carried any money).*/
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.creator_id = p_creator_id AND (p_product_id IS NULL OR o.product_id = p_product_id) AND coalesce(o.source_detail ->> 'surface', '') <> 'admin' ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status, 'pending') = 'pending') AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.property_type IS DISTINCT FROM 'onepage' ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'refunded_at') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 324: orders has no refunded_at or creator_id here; the refunds index is skipped.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_creator_refunded_at ON public.orders (creator_id, refunded_at) WHERE status = 'refunded'; END $do$;
DO $do$ BEGIN IF to_regclass('public.ledger_events') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'ledger_events' AND column_name = 'creator_id') THEN RAISE NOTICE 'part 324: there is no ledger_events with creator_id here; the ledger refunds index is skipped.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS ledger_events_creator_refund_time ON public.ledger_events (creator_id, created_at) WHERE event_type = 'refund'; END $do$;
notify pgrst, 'reload schema';
